// ── Publishing an event (Producer) ──
public class OrderService {
    private readonly IMessageBus _bus;

    public async Task PlaceOrderAsync(OrderDto dto) {
        var order = await _db.CreateOrderAsync(dto);

        // Publish event — consumers handle the rest
        await _bus.PublishAsync(new OrderPlacedEvent {
            OrderId = order.Id,
            CustomerId = dto.CustomerId,
            Amount = dto.Total,
            Timestamp = DateTime.UtcNow
        });
    }
}

// ── Consuming events (multiple consumers) ──
// Consumer 1: Send confirmation email
public class EmailConsumer : IConsumer<OrderPlacedEvent> {
    public async Task Consume(OrderPlacedEvent e) {
        await _emailService.SendAsync(e.CustomerId, $"Order #{e.OrderId} confirmed!");
    }
}

// Consumer 2: Update inventory
public class InventoryConsumer : IConsumer<OrderPlacedEvent> {
    public async Task Consume(OrderPlacedEvent e) {
        await _inventoryService.ReserveStockAsync(e.OrderId);
    }
}

// Consumer 3: Analytics
public class AnalyticsConsumer : IConsumer<OrderPlacedEvent> {
    public async Task Consume(OrderPlacedEvent e) {
        await _analytics.TrackOrderAsync(e.Amount);
    }
}

